#!/usr/bin/env node
// 测试 fixture：模拟官方插件 xlmerge 的可执行入口（非真实包，仅本仓库测试用）。
// 行为契约（与 tests/cli.integration.test.ts 的断言一一对应）：
// - 第一行 stdout 始终输出 JSON 载荷 { argv, env }（路由/转发的解析点）；
// - --help 在第一行 JSON 之后追加带 resolve_xlsx_conflict.py 的用法文本（路由落点标记）；
// - --exit-42 → 退出码 42（退出码原样传播测试）；
// - --hold → 写就绪文件后驻留，收到 SIGTERM/SIGINT 时写回执后退出（信号转发测试，POSIX）；
// - stderr 固定输出 fixture-stderr-marker（“插件未被调用”的负向断言哨兵）。
import fs from "node:fs";

process.stderr.write("fixture-stderr-marker\n");

const argv = process.argv.slice(2);
const payload = {
  argv,
  env: {
    V_CLI_HOST_VERSION: process.env.V_CLI_HOST_VERSION,
    V_CLI_PLUGIN_API: process.env.V_CLI_PLUGIN_API,
    V_CLI_INVOKED_BY: process.env.V_CLI_INVOKED_BY,
  },
};
process.stdout.write(JSON.stringify(payload) + "\n");

if (argv.includes("--help")) {
  process.stdout.write(
    [
      "xlmerge (fixture) — resolve_xlsx_conflict.py",
      "",
      "Usage: xlmerge --repo <repo> detect",
    ].join("\n") + "\n",
  );
  process.exit(0);
}

if (argv.includes("--exit-42")) process.exit(42);

if (argv.includes("--hold")) {
  if (process.env.V_CLI_TEST_READY_FILE) {
    fs.writeFileSync(process.env.V_CLI_TEST_READY_FILE, "READY", "utf-8");
  }
  if (process.env.V_CLI_TEST_TERM_FILE) {
    process.on("SIGTERM", () => {
      fs.writeFileSync(process.env.V_CLI_TEST_TERM_FILE, "TERM", "utf-8");
      process.exit(143);
    });
    process.on("SIGINT", () => {
      fs.writeFileSync(process.env.V_CLI_TEST_TERM_FILE, "TERM", "utf-8");
      process.exit(130);
    });
  }
  setInterval(() => {}, 1000); // 驻留等待信号
}